import axios from 'axios';

// Base URL for your backend
const BASE_URL = 'http://localhost:8082/api';

// Create axios instance with default config
const api = axios.create({
  baseURL: BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor to add JWT token to all requests
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor to handle token expiration
api.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    // Only handle 401 errors for authentication endpoints
    // Don't auto-logout for product/cart API failures
    if (error.response?.status === 401 && 
        (error.config?.url?.includes('/auth/') || 
         error.config?.url?.includes('/user/profile'))) {
      // Token is invalid or expired for auth-related endpoints
      localStorage.removeItem('token');
      localStorage.removeItem('userRole');
      localStorage.removeItem('username');
      localStorage.removeItem('profilePictureUrl');
      window.dispatchEvent(new Event('localStorageUpdated'));
      
      // Redirect to login page
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

// API functions for different operations
export const authAPI = {
  login: (credentials) => api.post('/auth/login', credentials),
  register: (userData) => api.post('/auth/register', userData),
  googleLogin: (token) => api.post('/auth/google', { token }),
};

export const productAPI = {
  // Get all products
  getAllProducts: () => api.get('/products'),
  
  // Get products by category
  getProductsByCategory: (categoryId) => api.get(`/products/category/${categoryId}`),
  
  // Get product by ID
  getProductById: (productId) => api.get(`/products/${productId}`),
  
  // Search products
  searchProducts: (query) => api.get(`/products/search?q=${query}`),
  
  // Get discounted products
  getDiscountedProducts: () => api.get('/products/discounted'),
};

export const userAPI = {
  // Get user profile
  getProfile: () => api.get('/user/profile'),
  
  // Update user profile
  updateProfile: (userData) => api.put('/user/profile', userData),
  
  // Get user orders
  getOrders: () => api.get('/user/orders'),
};

export const cartAPI = {
  // Get user's cart
  getCart: () => api.get('/cart'),
  
  // Add item to cart
  addToCart: (productId, quantity) => api.post('/cart/add', { productId, quantity }),
  
  // Update cart item quantity
  updateCartItem: (itemId, quantity) => api.put(`/cart/item/${itemId}`, { quantity }),
  
  // Remove item from cart
  removeFromCart: (itemId) => api.delete(`/cart/item/${itemId}`),
  
  // Clear cart
  clearCart: () => api.delete('/cart/clear'),
};

// Helper function to check if user is authenticated
export const isAuthenticated = () => {
  const token = localStorage.getItem('token');
  return !!token;
};

// Helper function to get user info from localStorage
export const getUserInfo = () => {
  return {
    token: localStorage.getItem('token'),
    username: localStorage.getItem('username'),
    role: localStorage.getItem('userRole'),
    profilePictureUrl: localStorage.getItem('profilePictureUrl'),
  };
};

// Helper function to logout user
export const logout = () => {
  localStorage.removeItem('token');
  localStorage.removeItem('userRole');
  localStorage.removeItem('username');
  localStorage.removeItem('profilePictureUrl');
  window.dispatchEvent(new Event('localStorageUpdated'));
  window.location.href = '/login';
};

export default api;
